import{g as a,ae as e,r as n,B as t}from"./chunks/framework.CZ-ntRvv.js";const _=JSON.parse('{"title":"useCall","description":"","frontmatter":{},"headers":[],"relativePath":"docs/data-fetching/use-call.md","filePath":"docs/data-fetching/use-call.md","lastUpdated":1790275646000}'),p={name:"docs/data-fetching/use-call.md"};function c(o,s,d,l,r,i){return e(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="usecall" tabindex="-1">useCall <a class="header-anchor" href="#usecall" aria-label="Permalink to “useCall”">​</a></h1><p><code>useCall</code> calls a whitelisted Frappe method or a REST endpoint and returns the response with its loading and error state. Apps on the older resource API can keep using <a href="./resource">Resources</a>, which stay supported through <code>1.x</code>.</p><h2 id="basic-example" tabindex="-1">Basic example <a class="header-anchor" href="#basic-example" aria-label="Permalink to “Basic example”">​</a></h2><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">Button</span><span class="s_1i4ay4"> @click</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">ping.reload()</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> :loading</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">ping.loading</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span><span class="s_6am9cx">Ping</span><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Button</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">pre</span><span class="s_1zd9e2">&gt;</span><span class="s_6am9cx">{{ ping.data }}</span><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">pre</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useCall</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> ping</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useCall</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  url</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">/api/v2/method/ping</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>The request is a <code>GET</code> and is sent as soon as <code>useCall</code> runs.</p><h2 id="send-a-request-on-demand" tabindex="-1">Send a request on demand <a class="header-anchor" href="#send-a-request-on-demand" aria-label="Permalink to “Send a request on demand”">​</a></h2><p>Set <code>immediate: false</code> and call <code>submit()</code> with the params:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useCall</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> renameTodo</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useCall</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  url</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">/api/v2/method/frappe.client.rename_doc</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  method</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">POST</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  immediate</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> false</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">async</span><span class="s_50ecpt"> function</span><span class="s_indoxt"> rename</span><span class="s_13ahmt">(</span><span class="s_fsg3al">name</span><span class="s_1jjt6x">,</span><span class="s_fsg3al"> newName</span><span class="s_13ahmt">)</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_29n2kq">  await</span><span class="s_22m8k2"> renameTodo</span><span class="s_1jjt6x">.</span><span class="s_indoxt">submit</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">    doctype</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">ToDo</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">    old_name</span><span class="s_1jjt6x">:</span><span class="s_22m8k2"> name</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">    new_name</span><span class="s_1jjt6x">:</span><span class="s_22m8k2"> newName</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  })</span></span>
<span class="line"><span class="s_13ahmt">}</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><h2 id="fetch-again-when-a-value-changes" tabindex="-1">Fetch again when a value changes <a class="header-anchor" href="#fetch-again-when-a-value-changes" aria-label="Permalink to “Fetch again when a value changes”">​</a></h2><p>Pass <code>params</code> as a function and set <code>refetch: true</code>. A new request goes out when a value it reads changes:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">ref</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">vue</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useCall</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> query</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> ref</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;&#39;</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> users</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useCall</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  url</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">/api/v2/method/frappe.desk.search.search_link</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_indoxt">  params</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> ()</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> ({</span><span class="s_r4oegk"> doctype</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">User</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> txt</span><span class="s_1jjt6x">:</span><span class="s_22m8k2"> query</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_13ahmt"> })</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  refetch</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> true</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to “Options”">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>url</code></td><td><code>string | Ref&lt;string&gt;</code></td><td>required</td><td>The URL path to call, such as <code>/api/v2/method/ping</code>. A ref changes it reactively.</td></tr><tr><td><code>method</code></td><td><code>&#39;GET&#39;</code>, <code>&#39;POST&#39;</code>, <code>&#39;PUT&#39;</code> or <code>&#39;DELETE&#39;</code></td><td><code>&#39;GET&#39;</code></td><td>The HTTP method. <code>GET</code> sends <code>params</code> in the query string, the others in the body.</td></tr><tr><td><code>params</code></td><td><code>object | () =&gt; object</code></td><td></td><td>The request params. Use the function form so reactive values are read again on each request.</td></tr><tr><td><code>immediate</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Sends the first request when <code>useCall</code> runs.</td></tr><tr><td><code>refetch</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Sends a new request when a reactive <code>url</code> or <code>params</code> value changes.</td></tr><tr><td><code>baseUrl</code></td><td><code>string</code></td><td><code>&#39;&#39;</code></td><td>A prefix for <code>url</code>, for a Frappe site on another origin.</td></tr><tr><td><code>initialData</code></td><td><code>TResponse</code></td><td></td><td>The value of <code>data</code> before the first response.</td></tr><tr><td><code>cacheKey</code></td><td><code>CacheKey</code></td><td></td><td>A string or an array such as <code>[&#39;todo&#39;, name]</code>. Saves the response. See <a href="#caching">Caching</a>.</td></tr><tr><td><code>staleOnError</code></td><td><code>boolean</code></td><td><code>false</code></td><td>With <code>cacheKey</code>, a failed request keeps showing the cached <code>data</code>. A Frappe error response still clears it.</td></tr><tr><td><code>transform</code></td><td><code>(data) =&gt; data</code></td><td></td><td>Changes the response before it goes into <code>data</code>. Returning <code>undefined</code> keeps the response as is.</td></tr><tr><td><code>beforeSubmit</code></td><td><code>(params) =&gt; void | Promise&lt;void&gt;</code></td><td></td><td>Runs before each <code>submit()</code>. If it throws, no request is sent and <code>submit()</code> rejects.</td></tr><tr><td><code>onSuccess</code></td><td><code>(data) =&gt; void</code></td><td></td><td>Called with the data after each successful request.</td></tr><tr><td><code>onError</code></td><td><code>(error: Error) =&gt; void</code></td><td></td><td>Called with the error after each failed request.</td></tr></tbody></table><h2 id="return-value" tabindex="-1">Return value <a class="header-anchor" href="#return-value" aria-label="Permalink to “Return value”">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>data</code></td><td><code>TResponse | null</code></td><td>The response data, or <code>null</code> before the first successful response.</td></tr><tr><td><code>error</code></td><td><code>Error | null</code></td><td>The error from the last request.</td></tr><tr><td><code>loading</code></td><td><code>boolean</code></td><td><code>true</code> while a request is in flight. Also available as <code>isFetching</code>.</td></tr><tr><td><code>isFinished</code></td><td><code>boolean</code></td><td><code>true</code> once the current request has settled, with or without an error.</td></tr><tr><td><code>params</code></td><td><code>object</code></td><td>The params of the current request: the last <code>submit()</code> params, or else the <code>params</code> option.</td></tr><tr><td><code>url</code></td><td><code>string</code></td><td>The full URL, with <code>baseUrl</code> and, for <code>GET</code>, the query string.</td></tr><tr><td><code>promise</code></td><td><code>Promise&lt;void&gt;</code></td><td>Resolves when the request in flight settles. It never rejects, so check <code>error</code> after it.</td></tr><tr><td><code>canAbort</code></td><td><code>boolean</code></td><td><code>true</code> while a request that can be aborted is in flight.</td></tr><tr><td><code>aborted</code></td><td><code>boolean</code></td><td><code>true</code> if the last request was aborted.</td></tr><tr><td><code>reload()</code></td><td><code>() =&gt; Promise&lt;TResponse | null&gt;</code></td><td>Sends a request with the current params. Resolves with the data, or <code>null</code> if it fails. Also available as <code>execute()</code> and <code>fetch()</code>.</td></tr><tr><td><code>submit(params?)</code></td><td><code>(params?) =&gt; Promise&lt;TResponse | null&gt;</code></td><td>Runs <code>beforeSubmit</code>, then sends a request with <code>params</code>, or the <code>params</code> option if omitted. Rejects if it fails.</td></tr><tr><td><code>reset()</code></td><td><code>() =&gt; void</code></td><td>Clears the params set by the last <code>submit()</code>.</td></tr><tr><td><code>abort()</code></td><td><code>() =&gt; void</code></td><td>Aborts the request in flight.</td></tr></tbody></table><p>These pages use <code>reload()</code> and <code>loading</code>. The other names do the same thing and stay in v1.</p><h3 id="refetch-and-submit" tabindex="-1"><code>refetch</code> and <code>submit</code> <a class="header-anchor" href="#refetch-and-submit" aria-label="Permalink to “refetch and submit”">​</a></h3><p>With <code>refetch: true</code>, a params change sends a request by itself. <code>submit()</code> waits for that request instead of sending a second one. It sends its own request when the change sent nothing: the same object passed again, <code>GET</code> params that build the same URL, or no argument at all.</p><p>A request belongs to a <code>submit()</code> if it was built after that call set its params. A request built before, even one still in flight, does not, and the <code>submit()</code> sends its own once that one settles.</p><p>Each <code>useCall</code> has one request slot, so:</p><ul><li>Two <code>submit()</code> calls in the same tick send <strong>one</strong> request with the params of the later call. Both resolve with its response.</li><li>A params change aborts the request in flight. Both callers resolve with the new response.</li></ul><p>When writes must run at the same time, give each its own <code>useCall</code>, or use the write members of <a href="./use-doc"><code>useDoc</code></a>, which send one request per submit.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to “Errors”">​</a></h2><p><strong>Writes reject, reads resolve.</strong> A failed write rejects, so code after <code>await</code> does not run as if it succeeded. A failed read resolves, so a template can keep showing the last value and show <code>error</code> next to it.</p><table tabindex="0"><thead><tr><th>Call</th><th>On failure</th></tr></thead><tbody><tr><td><code>submit()</code> on <code>useCall</code> and <code>useNewDoc</code>, and on the write members of <code>useDoc</code>, <code>useList</code> and <code>useDoctype</code></td><td>Rejects</td></tr><tr><td><code>reload()</code>, <code>execute()</code> and <code>fetch()</code></td><td>Resolves and sets <code>error</code></td></tr></tbody></table><p>Both kinds set <code>error</code>, and call <code>onError</code> where the composable takes one.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_50ecpt">try</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_29n2kq">  await</span><span class="s_22m8k2"> renameTodo</span><span class="s_1jjt6x">.</span><span class="s_indoxt">submit</span><span class="s_13ahmt">({ </span><span class="s_r4oegk">doctype</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">ToDo</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> old_name</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">todo-1</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> new_name</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">todo-2</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_22m8k2">  toast</span><span class="s_1jjt6x">.</span><span class="s_indoxt">success</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">Renamed</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_13ahmt">}</span><span class="s_50ecpt"> catch</span><span class="s_13ahmt"> (</span><span class="s_22m8k2">error</span><span class="s_13ahmt">)</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_22m8k2">  toast</span><span class="s_1jjt6x">.</span><span class="s_indoxt">error</span><span class="s_13ahmt">(</span><span class="s_22m8k2">error</span><span class="s_1jjt6x">.</span><span class="s_11933w">message</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_13ahmt">}</span></span></code></pre></div><h3 id="which-error-class" tabindex="-1">Which error you get <a class="header-anchor" href="#which-error-class" aria-label="Permalink to “Which error you get”">​</a></h3><p>The error class depends on the API that sent the request. All three are plain <code>Error</code> objects with extra fields:</p><table tabindex="0"><thead><tr><th>API</th><th>Error</th><th>Kind</th><th>Extra fields</th></tr></thead><tbody><tr><td><code>useCall</code>, <code>useDoc</code>, <code>useList</code>, <code>useDoctype</code>, <code>useNewDoc</code></td><td><a href="./../other/utilities#frapperesponseerror"><code>FrappeResponseError</code></a></td><td>class</td><td><code>title</code>, <code>type</code>, <code>exception</code>, <code>indicator</code></td></tr><tr><td><code>call</code>, <code>frappeRequest</code>, <code>createResource</code> and the other v1 resources</td><td><a href="./../other/utilities#frapperequesterror"><code>FrappeResourceError</code></a></td><td>type only</td><td><code>messages</code>, <code>exc_type</code>, <code>exc</code>, <code>status</code>, <code>response</code></td></tr><tr><td><code>upload</code>, <code>useFileUpload</code>, <code>FileUploadHandler</code></td><td><a href="./../other/utilities#uploaderror"><code>UploadError</code></a></td><td>class</td><td><code>kind</code>, <code>status</code>, <code>messages</code>, <code>response</code></td></tr></tbody></table><p><code>FrappeResponseError</code> and <code>UploadError</code> are classes, so <code>instanceof</code> works:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_50ecpt">if</span><span class="s_13ahmt"> (</span><span class="s_22m8k2">error</span><span class="s_2ekfrt"> instanceof</span><span class="s_euu481"> FrappeResponseError</span><span class="s_13ahmt">)</span><span class="s_22m8k2"> console</span><span class="s_1jjt6x">.</span><span class="s_indoxt">log</span><span class="s_13ahmt">(</span><span class="s_22m8k2">error</span><span class="s_1jjt6x">.</span><span class="s_11933w">title</span><span class="s_13ahmt">)</span></span></code></pre></div><p><code>FrappeResourceError</code> is only a TypeScript type, so there is nothing to test with <code>instanceof</code>. Check a field instead:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_50ecpt">if</span><span class="s_13ahmt"> (</span><span class="s_22m8k2">error</span><span class="s_1jjt6x">.</span><span class="s_11933w">exc_type</span><span class="s_50ecpt"> ===</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">PermissionError</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span><span class="s_indoxt"> showPermissionMessage</span><span class="s_13ahmt">()</span></span></code></pre></div><h2 id="caching" tabindex="-1">Caching <a class="header-anchor" href="#caching" aria-label="Permalink to “Caching”">​</a></h2><p>With <code>cacheKey</code>, the response is saved in memory and in IndexedDB. The next <code>useCall</code> with the same key shows the saved value at once, sends a fresh request, and replaces the value when the response arrives.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> todo</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useCall</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  url</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">/api/v2/method/frappe.client.get</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  params</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span><span class="s_r4oegk"> doctype</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">ToDo</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> name</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">todo-1</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  cacheKey</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">todo</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">todo-1</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">]</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span></code></pre></div><h3 id="cache-namespace" tabindex="-1">One cache per user <a class="header-anchor" href="#cache-namespace" aria-label="Permalink to “One cache per user”">​</a></h3><p>Each signed-in user has their own cache. You do not have to set anything up. Every <code>cacheKey</code> of <code>useCall</code> and <code>useList</code>, and every document that <a href="./use-doc#shared-cache"><code>useDoc</code></a> saves, is stored under the user who is signed in. frappe-ui reads the user from the <code>user_id</code> cookie that Frappe sets at login. If another user signs in on the same browser, they do not see the first user&#39;s saved values.</p><p>Guests, and requests with no session, share one cache that is not tied to a user. A signed-in user never reads from it, so nothing a user saved reaches a guest.</p><p>Reload the page after a user signs in or out. The data already loaded, and any request still waiting for its response, belong to the user who was signed in before. Without a reload, they can be shown to the new user and saved under the new user&#39;s key. Frappe&#39;s own login and logout pages reload the page.</p><p>Other users&#39; values stay in IndexedDB until the browser clears them. The v1 resources (<code>createResource</code>, <code>createDocumentResource</code>) do not keep a cache per user.</p>`,42)])])}const u=a(p,[["render",c]]);export{_ as __pageData,u as default};
